call.command:
cat > solve.mjs <<'EOF'
import { createHash } from 'node:crypto';

let text = 'seed';
for (let i = 0; i < 24; i++) {
  text = createHash('sha256').update(text, 'utf8').digest('hex');
}
process.stdout.write('RESULT ' + text + '\n');
EOF
node --version && ls -la

out=$(node solve.mjs); echo "node said: $out"; rc=$?; echo "exit=$rc"; py=$(python3 -c "import hashlib; s='seed'
for i in range(24): s=hashlib.sha256(s.encode('utf-8')).hexdigest()
print('RESULT', s)"); echo "python said: $py"; [ "$out" = "$py" ] && [ "$out" = "RESULT 9b1aca1c8c242048d47d3ed8e395af404d02973271ae9e57bce534a25a6c6fa5" ] && echo MATCH_EXPECTED || echo MISMATCH
